    @Override protected void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(HEADER);getWindow().setNavigationBarColor(BG);profiles=new ProfileStore(this);bridges=new BridgeStore(this);livePrefs=getSharedPreferences(TelemetryServiceV10.PREFS,MODE_PRIVATE);uiPrefs=getSharedPreferences("ccop_v10_ui",MODE_PRIVATE);lastPlugEvent=uiPrefs.getInt("handledPlugEvent",-1);setContentView(shell());show(Tab.OVERVIEW);startLiveService();handler.post(uiPoll);if(Build.VERSION.SDK_INT>=33)try{requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},900);}catch(Throwable ignored){}}
