    private void startLiveService(){Intent i=new Intent(this,TelemetryServiceV10.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}
    private void loadLive(){String raw=livePrefs.getString(TelemetryServiceV10.KEY_LATEST,"");long updated=livePrefs.getLong("updatedAt",0);JSONObject next=null;try{if(!raw.isEmpty())next=new JSONObject(raw);}catch(Exception ignored){}if(next==null||System.currentTimeMillis()-updated>5000)next=directFallback();if(next!=null)live=next;updateHeader();updateVisible();int ev=live.optInt("plugEventId",-1);if(isPlugged()&&ev>=0&&ev!=lastPlugEvent){lastPlugEvent=ev;uiPrefs.edit().putInt("handledPlugEvent",ev).apply();handler.postDelayed(this::autoConfigureOnPlug,350);}}
    private JSONObject directFallback(){JSONObject j=new JSONObject();try{Intent b=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));if(b==null)return j;int level=b.getIntExtra(BatteryManager.EXTRA_LEVEL,-1),scale=b.getIntExtra(BatteryManager.EXTRA_SCALE,100),plug=b.getIntExtra(BatteryManager.EXTRA_PLUGGED,0),status=b.getIntExtra(BatteryManager.EXTRA_STATUS,BatteryManager.BATTERY_STATUS_UNKNOWN),mv=b.getIntExtra(BatteryManager.EXTRA_VOLTAGE,-1),t=b.getIntExtra(BatteryManager.EXTRA_TEMPERATURE,Integer.MIN_VALUE);BatteryManager bm=(BatteryManager)getSystemService(BATTERY_SERVICE);int ua=bm.getIntProperty(BatteryManager.BATTERY_PROPERTY_CURRENT_NOW);boolean plugged=plug!=0,charging=plugged&&(status==BatteryManager.BATTERY_STATUS_CHARGING||status==BatteryManager.BATTERY_STATUS_FULL);j.put("ts",System.currentTimeMillis());j.put("plugged",plugged);j.put("charging",charging);if(level>=0&&scale>0)j.put("phonePct",100.0*level/scale);if(mv>0)j.put("batteryV",mv/1000.0);if(ua!=Integer.MIN_VALUE){double ma=ua/1000.0;j.put("batteryMa",ma);if(mv>0)j.put("batteryW",(charging?1:-1)*Math.abs((mv/1000.0)*(ua/1e6)));}if(t!=Integer.MIN_VALUE)j.put("temperatureC",t/10.0);j.put("fallback",true);}catch(Exception ignored){}return j;}

    private View shell(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(BG);root.setOnApplyWindowInsetsListener((v,in)->{v.setPadding(0,in.getSystemWindowInsetTop(),0,in.getSystemWindowInsetBottom());return in;});LinearLayout h=new LinearLayout(this);h.setOrientation(LinearLayout.VERTICAL);h.setPadding(dp(18),dp(8),dp(18),dp(10));h.setBackgroundColor(HEADER);LinearLayout tr=new LinearLayout(this);tr.setGravity(Gravity.CENTER_VERTICAL);ImageView icon=new ImageView(this);icon.setImageResource(R.drawable.ic_ccop_lademonitor);tr.addView(icon,new LinearLayout.LayoutParams(dp(48),dp(48)));LinearLayout tt=new LinearLayout(this);tt.setOrientation(LinearLayout.VERTICAL);tt.setPadding(dp(10),0,0,0);tt.addView(txt("CCOP LadeMonitor",28,TEXT,true));tt.addView(txt("LIVE · AUTO CONFIG · NO DEMO",10,MUTED,true));tr.addView(tt,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1));h.addView(tr);header=txt("● Live-Daten werden gestartet …",13,OK,false);header.setPadding(0,dp(5),0,0);h.addView(header);root.addView(h);content=new LinearLayout(this);root.addView(content,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,0,1));nav=new LinearLayout(this);nav.setOrientation(LinearLayout.HORIZONTAL);nav.setBackgroundColor(Color.rgb(5,16,23));addNav(Tab.OVERVIEW,"⌂\nÜbersicht");addNav(Tab.LIVE,"⌁\nLive");addNav(Tab.PROFILES,"▱\nProfile");addNav(Tab.BRIDGE,"⌘\nBridge");addNav(Tab.HISTORY,"◷\nVerlauf");addNav(Tab.REPORT,"▥\nBericht");root.addView(nav,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,dp(68)));return root;}
