    private void show(Tab t){current=t;refs.clear();content.removeAllViews();ScrollView s=new ScrollView(this);s.setFillViewport(true);LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.setPadding(dp(18),dp(16),dp(18),dp(22));s.addView(b);content.addView(s,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.MATCH_PARENT));if(t==Tab.OVERVIEW)overview(b);else if(t==Tab.LIVE)liveTab(b);else if(t==Tab.PROFILES)profilesTab(b);else if(t==Tab.BRIDGE)bridgeTab(b);else if(t==Tab.HISTORY)historyTab(b);else reportTab(b);for(int i=0;i<nav.getChildCount();i++){TextView v=(TextView)nav.getChildAt(i);v.setTextColor(v.getTag()==t?CYAN:MUTED);}updateVisible();}
    private void section(LinearLayout b,String title,String sub){b.addView(txt(title,29,TEXT,true));TextView x=txt(sub,14,MUTED,false);x.setPadding(0,dp(2),0,dp(14));b.addView(x);}private LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(15),dp(14),dp(15),dp(14));c.setBackground(round(PANEL,LINE,18));return c;}private void addCard(LinearLayout b,View v){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);p.setMargins(0,0,0,dp(11));b.addView(v,p);}private TextView ref(String k,String s,int size,int color,boolean bold){TextView v=txt(s,size,color,bold);refs.put(k,v);return v;}private void metric(LinearLayout c,String label,String key){LinearLayout r=new LinearLayout(this);r.setGravity(Gravity.CENTER_VERTICAL);r.addView(txt(label,13,MUTED,false),new LinearLayout.LayoutParams(0,dp(39),1));TextView v=ref(key,"—",14,TEXT,true);v.setGravity(Gravity.END|Gravity.CENTER_VERTICAL);r.addView(v);c.addView(r);}

    private void overview(LinearLayout b){section(b,"Gesamtenergie & Gerätepool","Live-Werte + bestätigte Bestände. Unbekannte externe SOCs werden nicht erfunden.");LinearLayout stat=card();stat.addView(ref("ovStatus","Live-Status wird gelesen …",18,OK,true));metric(stat,"Smartphone","ovPhone");metric(stat,"Netto-Leistung","ovPower");metric(stat,"Aktive Quelle","ovSource");metric(stat,"Aktives Kabel","ovCable");metric(stat,"Aktive Bridge","ovBridge");addCard(b,stat);LinearLayout total=card();total.addView(txt("Gesamtenergie · bekannte Akkus",17,TEXT,true));total.addView(ref("aggPct","— %",44,BLUE,true));ProgressBar pb=progress();pb.setTag("aggBar");total.addView(pb,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,dp(9)));total.addView(ref("aggWh","— Wh",13,MUTED,false));addCard(b,total);LinearLayout run=card();run.addView(txt("Gesamtlaufzeit-Prognose",16,TEXT,true));run.addView(ref("runtime","—",27,CYAN,true));run.addView(txt("Nur bei Akkubetrieb und messbarer Netto-Entladeleistung.",11,MUTED,false));addCard(b,run);LinearLayout inv=card();inv.addView(txt("Akkus & Quellen",17,TEXT,true));inv.addView(phoneRow());for(ProfileStore.Profile p:profiles.loadActiveInventory())inv.addView(profileRow(p));addCard(b,inv);Button go=primary("LIVE ÜBERWACHEN");go.setOnClickListener(v->show(Tab.LIVE));addCard(b,go);}
